Clase Circulo
    Privado Definir radio Como Entero;

    Metodo Constructor(unRadio Como Entero)
        Este.radio <- unRadio;
    FinMetodo

    Publico Metodo Perimetro() Como Real
        Retornar 2 * Este.radio * 3.14;
    FinMetodo

    Publico Metodo Area() Como Real
        Retornar Este.radio * Este.radio * 3.14;
    FinMetodo
FinClase

Proceso CalcularCirculo
    Definir radio Como Entero;
    Definir circulo Como Circulo;
    Leer radio;
    circulo <- Nuevo Circulo(radio);
    Escribir circulo.Perimetro();
    Escribir circulo.Area();
FinProceso
